"""대한민국 / 과학 중학교 3학년（2022 개정 중학교 1~3학년군 (16)~(23)）"""
from kr_sci import H, nq, num


def UNITS(g):
    return G9()


def f_reaction(R):
    k = R.choice(["mass", "ratio", "gasvol", "mgo"])
    if k == "mass":
        a, b = R.choice([(4, 16), (12, 32), (2, 16), (24, 16), (56, 32), (28, 6)])
        what = R.choice(["두 물질 A와 B", "반응물 A와 B"])
        return nq("%s가 완전히 반응하여 한 가지 생성물이 만들어졌습니다. A %d g과 B %d g이 모두 반응했다면 생성물의 질량은 몇 g일까요?" % (what, a, b), a + b, [abs(a - b), a * b, b, a + b / 2], "g",
                  "질량 보존 법칙: 반응물의 총질량 = 생성물의 총질량 = %d + %d = %d g입니다." % (a, b, a + b))
    if k == "ratio":
        cu = R.choice([4, 8, 12, 16, 20, 2])
        return nq("구리와 산소는 4 : 1의 질량비로 반응하여 산화 구리(Ⅱ)를 만듭니다. 구리 %d g이 모두 반응하면 산화 구리(Ⅱ)는 몇 g 생길까요?" % cu, cu * 5 / 4, [cu / 4, cu * 4, cu + 1, cu * 5], "g",
                  "필요한 산소 = %d ÷ 4 = %s g, 산화 구리(Ⅱ) = %d + %s = %s g입니다." % (cu, num(cu / 4), cu, num(cu / 4), num(cu * 5 / 4)))
    if k == "gasvol":
        h = R.choice([20, 40, 60, 100, 30, 80])
        return nq("같은 온도와 압력에서 수소 기체와 산소 기체는 2 : 1의 부피비로 반응하여 수증기를 만듭니다(2H₂ + O₂ → 2H₂O). 수소 %d mL가 모두 반응하는 데 필요한 산소는 몇 mL일까요?" % h, h / 2, [h * 2, h, h * 3 / 2], "mL",
                  "기체 반응 법칙: 수소 : 산소 = 2 : 1이므로 %d ÷ 2 = %s mL입니다." % (h, num(h / 2)))
    mg = R.choice([3, 6, 9, 12, 24, 1.5])
    return nq("마그네슘과 산소는 3 : 2의 질량비로 반응합니다. 마그네슘 %s g을 완전히 연소시킬 때 필요한 산소는 몇 g일까요?" % num(mg), mg * 2 / 3, [mg * 3 / 2, mg + 2, mg * 5 / 3, mg / 3], "g",
              "산소 = %s × 2 ÷ 3 = %s g입니다." % (num(mg), num(mg * 2 / 3)))


def f_energy(R):
    k = R.choice(["v", "work", "pe", "ke", "fall"])
    if k == "v":
        d, t = R.choice([(100, 20), (300, 60), (1200, 300), (50, 10), (90, 30), (360, 120)])
        return nq("물체가 %d m를 %d초 동안 일정한 속력으로 이동했습니다. 속력은 몇 m/s일까요?" % (d, t), d / t, [d * t, t / d, d - t], "m/s", "속력 = 이동 거리 ÷ 걸린 시간 = %d ÷ %d = %s m/s입니다." % (d, t, num(d / t)))
    if k == "work":
        F, s = R.choice([(10, 5), (20, 3), (50, 2), (100, 4), (5, 8), (30, 10)])
        return nq("물체에 %d N의 힘을 가하여 힘의 방향으로 %d m 이동시켰습니다. 한 일은 몇 J일까요?" % (F, s), F * s, [F / s, F + s, s / F], "J", "일 = 힘 × 이동 거리 = %d × %d = %d J입니다." % (F, s, F * s))
    if k == "pe":
        m, h = R.choice([(1, 2), (2, 5), (5, 3), (10, 1), (0.5, 4), (3, 10)])
        return nq("질량 %s kg인 물체를 지면에서 %s m 높이로 들어 올렸습니다. 지면을 기준으로 한 중력에 의한 위치 에너지는 몇 J일까요? (위치 에너지 = 9.8 × 질량 × 높이)" % (num(m), num(h)), 9.8 * m * h,
                  [m * h, 9.8 * m, 9.8 * h, 9.8 * m * h / 2], "J", "Eₚ = 9.8mh = 9.8 × %s × %s = %s J입니다." % (num(m), num(h), num(9.8 * m * h)))
    if k == "ke":
        m, v = R.choice([(2, 3), (4, 5), (10, 2), (1, 10), (0.5, 4), (6, 2)])
        return nq("질량 %s kg인 물체가 %s m/s의 속력으로 움직입니다. 운동 에너지는 몇 J일까요? (운동 에너지 = ½ × 질량 × 속력²)" % (num(m), num(v)), 0.5 * m * v * v, [m * v, m * v * v, 0.5 * m * v], "J",
                  "Eₖ = ½mv² = ½ × %s × %s² = %s J입니다." % (num(m), num(v), num(0.5 * m * v * v)))
    m, h = R.choice([(1, 5), (2, 10), (0.5, 20), (4, 2.5), (2, 3)])
    pe = 9.8 * m * h
    return nq("질량 %s kg인 공이 %s m 높이에서 자유 낙하합니다. 공기 저항을 무시할 때 지면에 닿기 직전의 운동 에너지는 몇 J일까요?" % (num(m), num(h)), pe, [m * h, pe / 2, 9.8 * h, pe * 2], "J",
              "역학적 에너지가 보존되므로 처음 위치 에너지 9.8 × %s × %s = %s J이 모두 운동 에너지로 전환됩니다." % (num(m), num(h), num(pe)))


